import java.util.*;import java.time.*;import java.net.*;import java.net.http.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.agent-mode=off","dreamcore.tasks.enabled=true","dreamcore.tasks.initial-delay-ms=3600000","dreamcore.knowledge.initial-delay-ms=3600000","dreamcore.object-lifecycle.enabled=false","dreamcore.departure.worker-enabled=false"})
class PublicationFeedbackIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired FeedbackService feedback;@Autowired RecommendationService recommendations;@Autowired DocumentService documents;@Autowired DocumentPublicationService publications;@Autowired PasswordEncoder passwords;@Autowired ObjectLifecycleService objects;@Autowired ObjectCleanupService cleanup;@Autowired ObjectScopeLifecycle scopes;@Autowired MaterialLifecycleService materials;@Autowired MaterialCleanupService materialCleanup;@Autowired ExperienceService experiences;@Autowired EvaluationAccess evaluation;@LocalServerPort int port;
 UUID tenant,author,reader,other,admin,privateSpace,readerSpace,shared,conversation,task;DocumentPublicationService.Publication publication;final String password="Synthetic-publication-feedback-password";final JsonMapper json=new JsonMapper();
 @BeforeEach void setup(){tenant=UUID.randomUUID();author=UUID.randomUUID();reader=UUID.randomUUID();other=UUID.randomUUID();admin=UUID.randomUUID();privateSpace=UUID.randomUUID();readerSpace=UUID.randomUUID();shared=UUID.randomUUID();conversation=UUID.randomUUID();task=UUID.randomUUID();
  db.update("INSERT INTO tenants(id,name) VALUES (?,'合成副本反馈')",tenant);
  for(UUID a:List.of(author,reader,other,admin)){db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,a+"@publication-feedback.test","合成用户",passwords.encode(password));db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");}
  db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'作者私人','PERSONAL'),(?,?,?,'读者私人','PERSONAL'),(?,?,?,'共享发布','SHARED')",privateSpace,tenant,author,readerSpace,tenant,reader,shared,tenant,admin);
  for(UUID a:List.of(author,reader,other))db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,?)",tenant,shared,a,a.equals(author));
  db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'合成发布源')",conversation,tenant,privateSpace,author);
  db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,finished_at) VALUES (?,?,?,?,?,'作者私人提示绝不开放','AGENT','SUCCEEDED',3,1,'合成发布正文：资料仅供流程验证。','verification',now())",task,tenant,privateSpace,conversation,author);
  var d=documents.create(author,tenant,conversation,task,null,UUID.randomUUID());publication=publications.publish(author,tenant,d.document().id(),1,UUID.randomUUID(),shared,null,null,null,"docx",true);
 }
 @AfterEach void finish(){db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE tenant_id=? AND status IN('QUEUED','RUNNING')",tenant);db.update("DELETE FROM login_attempts WHERE bucket=?",IdentityService.hash("ip:127.0.0.1"));}
 FeedbackService.Target target(UUID who){return recommendations.list(who,tenant,null,0,20,null).items().stream().filter(i->i.content().kind().equals("PUBLICATION")).findFirst().orElseThrow().feedbackTarget();}
 FeedbackService.Assessment useful(){return new FeedbackService.Assessment("USEFUL",List.of(),"");}
 FeedbackService.Assessment negative(){return new FeedbackService.Assessment("NOT_USEFUL",List.of("INACCURATE"),"仅本人的纠错意见");}
 FeedbackService.Feedback create(UUID who){return feedback.create(who,tenant,UUID.randomUUID(),target(who),negative());}
 UUID version(UUID feedback,int revision){return db.queryForObject("SELECT id FROM feedback_versions WHERE feedback_id=? AND revision=?",UUID.class,feedback,revision);}
 UUID record(UUID version){return db.queryForObject("SELECT id FROM object_lifecycle WHERE kind='FEEDBACK_VERSION' AND object_id=?",UUID.class,version);}
 @Autowired ExperienceAnalysisQueue experienceQueue;
 @Test void automaticIntakeReadsOnlyPublishedParsedCopyAndNeverAuthorsPrivateInput(){
  db.update("UPDATE conversation_tasks SET execution_class='live' WHERE id=?",task);var opinion=create(reader);experienceQueue.discover();
  assertNull(experienceQueue.claim(tenant)); // Parsing unavailable, never fall back to the author's document/task.
  UUID run=UUID.randomUUID(),chunk=UUID.randomUUID();
  db.update("INSERT INTO knowledge_runs(id,tenant_id,workspace_id,material_id,version_id,generation,requested_by,status) SELECT ?,?,?,?,?,coalesce(max(generation),0)+1,?,'READY' FROM knowledge_runs WHERE version_id=?",run,tenant,shared,publication.materialId(),publication.materialVersionId(),reader,publication.materialVersionId());
  db.update("INSERT INTO knowledge_chunks(id,tenant_id,workspace_id,material_id,version_id,run_id,ordinal,locator,method,content) VALUES (?,?,?,?,?,?,0,'p1','TEXT','合成独立发布副本正文')",chunk,tenant,shared,publication.materialId(),publication.materialVersionId(),run);
  db.update("UPDATE experience_analysis_items SET next_attempt_at=now() WHERE tenant_id=?",tenant);var job=experienceQueue.claim(tenant);assertNotNull(job);
  String input=json.writeValueAsString(job.inputs());assertTrue(input.contains("合成独立发布副本正文"));assertTrue(input.contains("仅本人的纠错意见"));assertFalse(input.contains("作者私人"));assertFalse(input.contains("TASK_INPUT"));
  db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);assertTrue(experienceQueue.active(job.id(),job.lease()));
 }
 @Test void readonlySharedReaderGetsOwnExactVersionWithoutAuthorsTaskOrOthersOpinions(){var t=target(reader);assertEquals("PUBLICATION",t.kind());assertNull(t.taskId());assertEquals(publication.id(),t.publicationId());assertEquals(publication.materialVersionId(),t.materialVersionId());var f=create(reader);assertEquals("PUBLISHED_COPY",f.snapshot().taskState());assertEquals("none",f.snapshot().executionClass());assertFalse(json.writeValueAsString(f).contains(task.toString()));assertFalse(json.writeValueAsString(f).contains("作者私人"));assertEquals(List.of(publication.materialVersionId()),db.queryForList("SELECT version_id FROM feedback_source_versions WHERE feedback_id=?",UUID.class,f.id()));
  for(UUID a:List.of(author,other,admin))assertThrows(IdentityException.class,()->feedback.get(a,tenant,f.id()));assertThrows(IdentityException.class,()->feedback.get(reader,UUID.randomUUID(),f.id()));assertEquals(false,db.queryForObject("SELECT can_maintain FROM workspace_members WHERE workspace_id=? AND account_id=?",Boolean.class,shared,reader));
  var their=create(other);assertNotEquals(f.id(),their.id());assertEquals(1,feedback.lookup(reader,tenant,t).feedback().revision());
 }
 @Test void forgedPresentationAndMixedPrivateTargetFailButIssuedPriorPresentationRemainsExact(){var t=target(reader);var alien=target(other);assertThrows(IdentityException.class,()->feedback.create(reader,tenant,UUID.randomUUID(),new FeedbackService.Target("PUBLICATION",null,0,0,"recommendation-v1",alien.presentationRevision(),t.publicationId(),t.materialVersionId(),1),useful()));assertThrows(IdentityException.class,()->feedback.create(reader,tenant,UUID.randomUUID(),new FeedbackService.Target("PUBLICATION",task,3,1,"recommendation-v1",t.presentationRevision(),t.publicationId(),t.materialVersionId(),1),useful()));assertThrows(IdentityException.class,()->feedback.create(reader,tenant,UUID.randomUUID(),new FeedbackService.Target("PUBLICATION",null,0,0,"recommendation-v1",t.presentationRevision(),t.publicationId(),t.materialVersionId(),2),useful()));
  var f=feedback.create(reader,tenant,UUID.randomUUID(),t,useful());feedback.followUp(reader,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("PREFERENCE",true,new FeedbackService.Preference("GENERAL","TABLE_FIRST",0),null,null));assertNotEquals(t.presentationRevision(),target(reader).presentationRevision());assertEquals(f.id(),feedback.lookup(reader,tenant,t).feedback().id());
 }
 @Test void concurrentRequestsEditWithdrawalAndExactReplayDoNotCountAsNewOpinions()throws Exception{var t=target(reader);UUID key=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(2)){var responses=pool.invokeAll(List.<Callable<FeedbackService.Feedback>>of(()->feedback.create(reader,tenant,key,t,useful()),()->feedback.create(reader,tenant,key,t,useful())));var f=responses.getFirst().get();assertEquals(f,responses.getLast().get());var edited=feedback.edit(reader,tenant,f.id(),UUID.randomUUID(),1,negative(),false);assertEquals(2,edited.revision());assertEquals(1,feedback.create(reader,tenant,key,t,useful()).revision());assertEquals("FEEDBACK_STATE_CHANGED",assertThrows(IdentityException.class,()->feedback.edit(reader,tenant,f.id(),UUID.randomUUID(),1,negative(),false)).code);assertEquals("WITHDRAWN",feedback.edit(reader,tenant,f.id(),UUID.randomUUID(),2,null,true).status());assertEquals(3,feedback.history(reader,tenant,f.id(),0,20).items().size());assertEquals(1,db.queryForObject("SELECT count(*) FROM feedback_entries WHERE actor_id=? AND tenant_id=?",Integer.class,reader,tenant));assertEquals(1,db.queryForObject("SELECT current_version FROM materials WHERE id=?",Integer.class,publication.materialId()));}}
 @Test void sourcePrivateTaskPurgePreservesIndependentPublicationAndReaderOpinion(){var f=create(reader);db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);assertEquals(f,feedback.get(reader,tenant,f.id()));assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,publication.materialId()));assertEquals(publication.materialVersionId(),target(reader).materialVersionId());assertNull(db.queryForObject("SELECT parent_id FROM object_lifecycle WHERE kind='FEEDBACK_VERSION' AND object_id=?",UUID.class,version(f.id(),1)));}
 @Test void revocationAndPublicationTrashBlockEveryOldEntryThenActualPurgeErasesOpinion(){var t=target(reader);UUID key=UUID.randomUUID();var f=feedback.create(reader,tenant,key,t,negative());db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",shared,reader);assertThrows(IdentityException.class,()->feedback.get(reader,tenant,f.id()));assertThrows(IdentityException.class,()->feedback.create(reader,tenant,key,t,negative()));assertThrows(IdentityException.class,()->feedback.history(reader,tenant,f.id(),0,20));db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,false)",tenant,shared,reader);
  materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),0,"TRASH");assertThrows(IdentityException.class,()->feedback.get(reader,tenant,f.id()));materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),1,"RESTORE");assertEquals(f.id(),feedback.get(reader,tenant,f.id()).id());
  // Explicit irreversible cleanup is tested with the existing service capability guard.
  db.update("INSERT INTO governance_capabilities(tenant_id,account_id,capability,workspace_id,granted_by) VALUES (?,?, 'LIFECYCLE_PURGE',?,?)",tenant,author,shared,admin);
  materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),2,"TRASH");materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),3,"PURGE");var job=materialCleanup.claim();assertNotNull(job);for(UUID object:materialCleanup.pending(job)){materialCleanup.remove(object);materialCleanup.removed(job,object);}materialCleanup.finish(job);assertEquals("{}",db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE feedback_id=?",String.class,f.id()));assertThrows(IdentityException.class,()->feedback.get(reader,tenant,f.id()));
 }
 @Test void explicitFollowupsRemainReadersPrivateWorkAndUseOnlyPublishedVersion(){var f=create(reader);var correction=feedback.followUp(reader,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("CORRECTION",true,null,"请核对已发布副本中的日期",null));assertEquals("WAITING_CAPABILITY",correction.acceptedState());assertEquals(readerSpace,correction.targetWorkspaceId());assertEquals(readerSpace,db.queryForObject("SELECT workspace_id FROM conversation_tasks WHERE id=?",UUID.class,correction.targetId()));assertEquals(reader,db.queryForObject("SELECT requested_by FROM conversation_tasks WHERE id=?",UUID.class,correction.targetId()));assertEquals(List.of(publication.materialVersionId()),db.queryForList("SELECT version_id FROM feedback_task_sources WHERE task_id=?",UUID.class,correction.targetId()));
  var content=new ExperienceService.Content("METHOD","读者私人候选","合成摘要","人工步骤",List.of("合成"),"获权副本","","","未核验","SOURCE_BOUND");var candidate=feedback.followUp(reader,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("EXPERIENCE_CANDIDATE",true,null,null,content));var e=experiences.get(reader,tenant,readerSpace,candidate.targetId(),candidate.targetVersion());assertEquals("CANDIDATE",e.status());assertEquals("NOT_EVALUATED",e.version().evaluation());assertEquals(1,e.version().evidence().size());assertEquals(publication.materialVersionId(),e.version().evidence().getFirst().referenceId());assertEquals(1,db.queryForObject("SELECT current_version FROM materials WHERE id=?",Integer.class,publication.materialId()));
  db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);assertEquals(candidate,feedback.actions(reader,tenant,f.id(),0,20).items().stream().filter(a->a.kind().equals("EXPERIENCE_CANDIDATE")).findFirst().orElseThrow());db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",shared,reader);assertEquals(0,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id=?",Integer.class,correction.targetId()));assertThrows(IdentityException.class,()->experiences.get(reader,tenant,readerSpace,candidate.targetId(),candidate.targetVersion()));
 }
 @Test void rawFeedbackRetentionClearsExactOldVersionWithoutExtendingOrErasingNewOpinion(){var f=create(reader);var v1=version(f.id(),1);feedback.edit(reader,tenant,f.id(),UUID.randomUUID(),1,useful(),false);db.update("UPDATE object_lifecycle SET original_anchor=now()-interval '181 days' WHERE object_id=? AND kind='FEEDBACK_VERSION'",v1);objects.bindPolicies();var due=db.queryForObject("SELECT policy_due FROM object_lifecycle WHERE object_id=?",java.sql.Timestamp.class,v1);objects.enqueueDue();cleanup.clean(record(v1));assertEquals("{}",db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE id=?",String.class,v1));assertEquals(2,feedback.get(reader,tenant,f.id()).revision());objects.bindPolicies();assertEquals(due,db.queryForObject("SELECT policy_due FROM object_lifecycle WHERE object_id=?",java.sql.Timestamp.class,v1));assertEquals("RAW_FEEDBACK",db.queryForObject("SELECT policy_key FROM object_lifecycle WHERE object_id=?",String.class,version(f.id(),2)));}
 @Test void departureScopeCleansOnlyLeavingReadersOpinionsThenTenantScopeClearsRemaining(){var f=create(reader);var otherOpinion=create(other);UUID execution=UUID.randomUUID();Instant due=Instant.now().minusSeconds(1).truncatedTo(java.time.temporal.ChronoUnit.MICROS),at=due.minusSeconds(30);var progress=scopes.isolateScope(tenant,reader,execution,at,due,100);assertTrue(progress.discoveryComplete());assertThrows(IdentityException.class,()->feedback.get(reader,tenant,f.id()));assertEquals(otherOpinion.id(),feedback.get(other,tenant,otherOpinion.id()).id());scopes.purgeScope(tenant,reader,execution,100);cleanup.clean(record(version(f.id(),1)));assertEquals("{}",db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE feedback_id=?",String.class,f.id()));assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,publication.materialId()));assertTrue(db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE feedback_id=?",String.class,otherOpinion.id()).contains("仅本人的"));
  UUID exit=UUID.randomUUID();scopes.isolateScope(tenant,null,exit,at,due,100);scopes.purgeScope(tenant,null,exit,100);cleanup.clean(record(version(otherOpinion.id(),1)));assertEquals("{}",db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE feedback_id=?",String.class,otherOpinion.id()));
 }
 @Test void publicationFeedbackCanBeAnExplicitPrivateEvaluationSignalWithoutModelSuccess(){var f=create(reader);var fact=evaluation.evidence(reader,tenant,shared,new EvaluationAccess.Evidence("FEEDBACK",f.id(),1,0));assertEquals("NO_MODEL",fact.mode());assertTrue(fact.exact());assertEquals("publication:"+publication.id(),fact.origin());assertEquals(List.of(publication.materialVersionId()),fact.sources());assertThrows(IdentityException.class,()->evaluation.evidence(author,tenant,shared,new EvaluationAccess.Evidence("FEEDBACK",f.id(),1,0)));}
 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<String> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}}
 @Test void actualHttpCreateLookupEditConflictAndPrivacyUsePublicContract()throws Exception{var c=new Client();assertEquals(200,c.send("POST","/api/v1/auth/login",Map.of("email",reader+"@publication-feedback.test","password",password),true).statusCode());var t=target(reader);String root="/api/v1/tenants/"+tenant+"/feedback";var response=c.send("POST",root,Map.of("requestId",UUID.randomUUID(),"target",t,"assessment",negative()),true);assertEquals(201,response.statusCode(),response.body());var f=json.readValue(response.body(),FeedbackService.Feedback.class);assertNull(f.target().taskId());assertFalse(response.body().contains(task.toString()));String query="?kind=PUBLICATION&taskRevision=0&attempt=0&presentationVersion=recommendation-v1&presentationRevision="+t.presentationRevision()+"&publicationId="+t.publicationId()+"&materialVersionId="+t.materialVersionId()+"&materialVersion=1";assertEquals(200,c.send("GET",root+query,null,false).statusCode());feedback.edit(reader,tenant,f.id(),UUID.randomUUID(),1,useful(),false);var conflict=c.send("POST",root+"/"+f.id(),Map.of("requestId",UUID.randomUUID(),"expectedRevision",1,"assessment",negative()),true);assertEquals(409,conflict.statusCode());assertEquals("1.0",json.readTree(conflict.body()).get("contractVersion").asString());assertEquals(403,c.send("POST",root,Map.of("requestId",UUID.randomUUID(),"target",t,"assessment",useful()),false).statusCode());}
}
